create policy "own id docs read" on storage.objects for select to authenticated using (bucket_id = 'id-documents' and ((storage.foldername(name))[1] = auth.uid()::text or public.has_role(auth.uid(), 'admin')));
create policy "own id docs insert" on storage.objects for insert to authenticated with check (bucket_id = 'id-documents' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "own id docs delete" on storage.objects for delete to authenticated using (bucket_id = 'id-documents' and (storage.foldername(name))[1] = auth.uid()::text);